using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text.Json;
using MphRead;
using MphRead.Mods.CustomWeapons;
using MphRead.Mods.Network;
using MphRead.Mods.Replay;

// Content-free graph envelope. This proves detached codecs only, not a loaded
// Scene graph, resources, rendering, sound, simulation or archive playback.
internal static class CustomReplayWorldChecks
{
    internal static int Run(string? output=null)
    {
        int checks=0;string root=Path.GetFullPath(output??Path.Combine(Path.GetTempPath(),"cw12f-world-"+Guid.NewGuid().ToString("N")));
        void Check(bool ok,string label){if(!ok)throw new InvalidOperationException(label);checks++;}
        void Reject(Action action,string label){try{action();}catch(Exception e)when(e is InvalidDataException or EndOfStreamException or ArgumentException or InvalidOperationException){Check(true,label);return;}throw new InvalidOperationException("Expected rejection: "+label);}
        try
        {
            Directory.CreateDirectory(root);var game=GameState.Current;var random=Rng.Current;using var f=new CustomReplayStateChecks.Fixture();var descriptor=ReplayCustomWeaponDescriptor.ForInspection(f.Context);
            byte[] Match(bool custom){var match=new MatchStatePacket{MatchId=7,AuthorityEpoch=f.World.Start.AuthorityEpoch,RoomKey="MP3 PROVING GROUND",NextRoomKey="",Mode=(byte)GameMode.Battle,RuleBits=custom?(uint)(MatchModifierFlags.RiftlineM7Available|MatchModifierFlags.PackagedWeaponAvailable):0};byte[] bytes=new byte[1+MatchStatePacket.Size];bytes[0]=(byte)PacketType.MatchState;match.Write(bytes.AsSpan(1));return bytes;}
            var current=new ReplayReplicaState();current.EnableCustomInspection(descriptor);current.Accept(Match(true),1);current.Accept(ReplayCustomWeaponFact.Bootstrap(f.Context).CopyBytes(),10);current.Accept(ReplayCustomWeaponFact.Baseline(f.Context,2,new(7,f.World.Start.AuthorityEpoch,f.Context.Bootstrap.Packages.MechanicsDigest,1001,8,0),f.Slots,Array.Empty<CustomReplicaFlight>()).CopyBytes(),11);for(int i=0;i<f.Context.Layout.Count;i++)current.Accept(f.Pickup(current.CustomWeapons!.Sequence+1,i).CopyBytes(),12);
            var initial=current.CaptureCheckpoint();current.Accept(ReplayCustomWeaponFact.Clock(f.Context,current.CustomWeapons!.Sequence+1,1004).CopyBytes(),20);var decoder=current.CaptureCheckpoint();
            byte[] Envelope(ushort version,byte features,ReplayReplicaCheckpoint construction,ReplayReplicaCheckpoint state,uint frame,string room="MP3 PROVING GROUND",GameMode mode=GameMode.Battle,byte[]? appendix=null,ulong map=17)
            {
                using var stream=new MemoryStream();using var writer=new BinaryWriter(stream);void Component(byte[] bytes){writer.Write(bytes.Length);writer.Write(bytes);}
                writer.Write(0x43575050u);writer.Write(version);writer.Write(features);writer.Write(ReplayWorldCheckpoint.ComputeContract(stable:true));writer.Write(room);writer.Write((int)mode);writer.Write(map);writer.Write(frame);writer.Write(123u);writer.Write(456u);Component(construction.Bytes.ToArray());Component(state.Bytes.ToArray());writer.Write(0);for(int i=0;i<5;i++)Component(Array.Empty<byte>());Component(new byte[8*57]);Component(new byte[4]);Component(new byte[184]);if(version==12)Component(appendix??ReplayWorldCheckpoint.CustomWorldAppendix(state));writer.Write(false);return stream.ToArray();
            }
            var nativeState=new ReplayReplicaState();nativeState.Accept(Match(false),1);byte[] native11=Envelope(11,7,nativeState.CaptureCheckpoint(),nativeState.CaptureCheckpoint(),1);using(var native=ReplayWorldCheckpoint.FromBytes(native11))Check(!native.HasCustomWeaponContract&&native.Bytes.SequenceEqual(native11),"default native11 codec exact bytes unchanged");
            byte[] worldBytes=Envelope(12,15,initial,decoder,20);using var world=ReplayWorldCheckpoint.FromCustomBytes(worldBytes);Check(world.HasCustomWeaponContract&&world.Frame==20&&world.CustomWeaponDescriptor!.CopyBytes().SequenceEqual(descriptor.CopyBytes()),"explicit world12 requires flags15 and exact descriptor");Check(world.ConstructionState().Bytes.SequenceEqual(initial.Bytes)&&world.DecoderState().Bytes.SequenceEqual(decoder.Bytes),"world12 preserves distinct original/current CP15 owners");
            var cold=new ReplayReplicaState();cold.RestoreCustomCheckpoint(world.DecoderState());Check(cold.CaptureCheckpoint().Bytes.SequenceEqual(decoder.Bytes)&&cold.CustomWeapons!.World==1004,"detached current decoder cold restores without Scene");
            byte[] appendix=ReplayWorldCheckpoint.CustomWorldAppendix(decoder);byte[] golden=new byte[72];"CWW1"u8.CopyTo(golden);golden[4]=1;SHA256.HashData(descriptor.CopyBytes()).CopyTo(golden,8);SHA256.HashData(current.CustomWeapons!.CaptureCheckpointBytes()).CopyTo(golden,40);Check(appendix.SequenceEqual(golden),"independent CWW1 version1 flags0 and exact descriptor/currentCWRS SHA256 pair");
            Reject(()=>{using var value=ReplayWorldCheckpoint.FromBytes(worldBytes);},"ordinary native FromBytes refuses world12");Reject(()=>{using var value=ReplayWorldCheckpoint.FromCustomBytes(native11);},"explicit custom decoder refuses native11");
            var metadata=world.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>());Check(metadata.FormatVersion==7&&metadata.OriginRecordingFrame==20&&metadata.WorldCheckpoint.SequenceEqual(worldBytes)&&ReplayTimelineArchive.ReadConstruction(metadata.Bootstrap.Packets.Single(),custom:true).Bytes.SequenceEqual(decoder.Bytes),"ClipMetadata7 uses CURRENT CP15 bootstrap, outerframe origin and exact world12");Check(ReplayFormatV3.ValidateCustomArchiveMetadata(metadata)!.CaptureCheckpoint().Bytes.SequenceEqual(decoder.Bytes),"initial archive7world validates exact bootstrap/current frontier");
            void Bad(byte[] bytes,string label){Reject(()=>{using var value=ReplayWorldCheckpoint.FromCustomBytes(bytes);},label);Check(world.Bytes.SequenceEqual(worldBytes)&&ReferenceEquals(GameState.Current,game)&&ReferenceEquals(Rng.Current,random),label+" leaves source/live facades unchanged");}
            foreach(int offset in new[]{0,4,6}){var bad=(byte[])worldBytes.Clone();bad[offset]=255;Bad(bad,"unknown world magic/version/flags "+offset);}foreach(int at in new[]{0,4,6,8,39,40,71}){var bad=(byte[])appendix.Clone();bad[at]^=128;Bad(Envelope(12,15,initial,decoder,20,appendix:bad),"CWW1 signature/version/flags/digest mismatch "+at);}
            Bad(Envelope(12,15,initial,decoder,19),"outerframe differs from current recording frame");Bad(Envelope(12,15,initial,decoder,20,room:"MP2 HARVESTER"),"outer room mismatch");Bad(Envelope(12,15,initial,decoder,20,mode:GameMode.Survival),"outer mode mismatch");Bad(Envelope(12,15,decoder,initial,12),"initial sequence/world frontier cannot exceed current");Bad(Envelope(12,15,nativeState.CaptureCheckpoint(),decoder,20),"custom world refuses initial native14 decoder");
            var otherContext=new ReplayCustomWeaponContext(new(f.World,43,f.Context.Layout.Digest,f.Context.Bootstrap.Packages),f.Package.Definition,f.Context.Layout);var other=new ReplayReplicaState();other.EnableCustomInspection(ReplayCustomWeaponDescriptor.ForInspection(otherContext));other.Accept(Match(true),1);other.Accept(ReplayCustomWeaponFact.Bootstrap(otherContext).CopyBytes(),10);other.Accept(ReplayCustomWeaponFact.Baseline(otherContext,2,new(7,f.World.Start.AuthorityEpoch,otherContext.Bootstrap.Packages.MechanicsDigest,1001,8,0),f.Slots,Array.Empty<CustomReplicaFlight>()).CopyBytes(),11);for(int i=0;i<otherContext.Layout.Count;i++)other.Accept(ReplayCustomWeaponFact.Pickup(otherContext,other.CustomWeapons!.Sequence+1,1001,i,new(new(otherContext.PickupWorld,otherContext.Layout.Placements[i].SpawnId,1),990,true,0)).CopyBytes(),12);other.Accept(ReplayCustomWeaponFact.Clock(otherContext,other.CustomWeapons!.Sequence+1,1004).CopyBytes(),20);var otherCheckpoint=other.CaptureCheckpoint();Bad(Envelope(12,15,initial,otherCheckpoint,20),"initial/current exact descriptor mismatch");
            var changedSlots=(CustomReplicaSlot[])f.Slots.Clone();changedSlots[1]=changedSlots[1] with{State=changedSlots[1].State with{Magazine=changedSlots[1].State.Magazine-1}};
            var sameSequence=new ReplayReplicaState();sameSequence.EnableCustomInspection(descriptor);sameSequence.Accept(Match(true),1);sameSequence.Accept(ReplayCustomWeaponFact.Bootstrap(f.Context).CopyBytes(),10);sameSequence.Accept(ReplayCustomWeaponFact.Baseline(f.Context,2,new(7,f.World.Start.AuthorityEpoch,f.Context.Bootstrap.Packages.MechanicsDigest,1001,8,0),changedSlots,Array.Empty<CustomReplicaFlight>()).CopyBytes(),11);for(int i=0;i<f.Context.Layout.Count;i++)sameSequence.Accept(f.Pickup(sameSequence.CustomWeapons!.Sequence+1,i).CopyBytes(),12);sameSequence.Accept(ReplayCustomWeaponFact.Clock(f.Context,sameSequence.CustomWeapons!.Sequence+1,1004).CopyBytes(),20);var conflictingFrontier=sameSequence.CaptureCheckpoint();Check(sameSequence.CustomWeapons!.Sequence==current.CustomWeapons!.Sequence&&!sameSequence.CustomWeapons!.CaptureCheckpointBytes().SequenceEqual(current.CustomWeapons.CaptureCheckpointBytes()),"independent valid owners can carry different supplied tables at same context and fact count");
            Bad(Envelope(12,15,decoder,conflictingFrontier,20),"same-sequence initial/current CWRS contradiction despite recomputed CWW1");using(var conflict=ReplayWorldCheckpoint.FromCustomBytes(Envelope(12,15,conflictingFrontier,conflictingFrontier,20)))Reject(()=>conflict.ValidateCustomArchive(metadata),"optional same-sequence state cannot replace archive bootstrap frontier");
            foreach(int cut in new[]{0,1,6,7,40,worldBytes.Length/2,worldBytes.Length-73,worldBytes.Length-1})Bad(worldBytes[..cut],"bounded world truncation "+cut);Bad(worldBytes.Concat(new byte[]{0}).ToArray(),"world trailing bytes");Reject(()=>{using var value=ReplayWorldCheckpoint.FromCustomBytes(new byte[ReplayWorldCheckpoint.MaximumBytes+1]);},"world maximum byte bound");
            var later=new ReplayReplicaState();later.RestoreCustomCheckpoint(decoder);var suffix=ReplayCustomWeaponFact.Clock(f.Context,later.CustomWeapons!.Sequence+1,1010);later.Accept(suffix.CopyBytes(),21);byte[] laterWorld=Envelope(12,15,initial,later.CaptureCheckpoint(),21);string path=Path.Combine(root,"world12.ppdemo");using(var writer=new ReplayWriterV3(path,metadata)){writer.WriteRecord(1,suffix.CopyBytes());writer.WriteCheckpoint(1,laterWorld);Reject(()=>writer.WriteCheckpoint(0,Envelope(12,15,conflictingFrontier,conflictingFrontier,20)),"optional writer rejects same-sequence different CWRS with valid CWW1");Reject(()=>writer.WriteCheckpoint(0,Envelope(12,15,otherCheckpoint,otherCheckpoint,20)),"optional world12 cannot cross archive context");writer.WriteRecord(5,new byte[]{255});Reject(()=>writer.WriteCheckpoint(2,laterWorld),"optional custom checkpoint index must match absolute worldframe");}
            void Read(string file,string label){using var reader=DemoReader.Open(file,out var result);Check(reader!=null&&result==ReplayOpenResult.Success&&reader.Metadata!.FormatVersion==7&&reader.Metadata.WorldCheckpoint.SequenceEqual(worldBytes),label+" initialworld12 exact");while(reader!.ReadNext()!=null){}Check(reader.LastResult==ReplayOpenResult.Success,label+" accepted stream complete");Check(reader.Checkpoints.Count==1&&reader.ReadCheckpoint(reader.Checkpoints[0]).SequenceEqual(laterWorld),label+" optional world12 checkpoint exact");}
            string ownedPath=Path.Combine(root,"owned-header.ppdemo");var callerMetadata=world.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>());using(var writer=new ReplayWriterV3(ownedPath,callerMetadata)){callerMetadata.Bootstrap.Packets[0].AsSpan().Clear();callerMetadata.WorldCheckpoint.AsSpan().Clear();writer.WriteRecord(1,suffix.CopyBytes());writer.WriteCheckpoint(1,laterWorld);writer.WriteRecord(5,new byte[]{255});}Read(ownedPath,"writer owns committed bootstrap/world header despite caller byte mutation");
            Read(path,"cold reopened archive");string extracted=Path.Combine(root,"extracted.ppdemo");Check(ReplayArchive.Extract(path,0,5,extracted)==ReplayOpenResult.Success,"world12 archive extraction");Read(extracted,"extracted archive");Check(ReplayArchive.Recover(path,out var recovered,out _),"world12 archive recovery");Read(recovered!,"recovered archive");
            string nativePath=Path.Combine(root,"native.ppdemo");using(var nativeWorld=ReplayWorldCheckpoint.FromBytes(native11))using(var writer=new ReplayWriterV3(nativePath,nativeWorld.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>())))Reject(()=>writer.WriteCheckpoint(19,worldBytes),"native archive cannot accept optional world12");
            var wrongArchive=world.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>());byte[] wrongMapWorld=Envelope(12,15,initial,decoder,20,map:18);using(var wrong=ReplayWorldCheckpoint.FromCustomBytes(wrongMapWorld))Reject(()=>wrong.ValidateCustomArchive(wrongArchive),"world/metadata map hash mismatch refuses");
            using(var native=ReplayWorldCheckpoint.FromBytes(native11))Check(native.Bytes.SequenceEqual(native11)&&native.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>()).FormatVersion==4,"native11 bytes/default metadata unchanged after custom codecs");
            File.WriteAllBytes(Path.Combine(root,"world12.bin"),worldBytes);File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{checks,scope="Content-free detached world12 envelopes and archive retention only. No loaded six-root Scene graph, render, resources, sound, collision, seek or playback admission claim."}));Console.WriteLine($"PASS {checks} detached custom world12/archive checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY WORLD FAIL "+error);return 1;}
    }
}
